IEnumerable<string[]> ReadCsvRows(string path)
{
    using StreamReader reader = File.OpenText(path);
    string? line;
    while ((line = reader.ReadLine()) is not null)
    {
        yield return line.Split(',');
    }
}

IEnumerable<string[]> rows = ReadCsvRows("attempts.csv");
// File not read yet — only the iterator object exists

foreach (string[] row in rows)
    Import(row);    // first pass — file opens here

foreach (string[] row in rows)
    Audit(row);     // second pass — file opens AGAIN

IEnumerable<string[]> rows = ReadCsvRows("attempts.csv");
List<string[]> snapshot = rows.ToList(); // reads entire file once

foreach (string[] row in snapshot) Import(row);
foreach (string[] row in snapshot) Audit(row); // same data, no re-read

IEnumerable<string[]> ReadBadCsv(string path)
{
    using var reader = File.OpenText(path);
    string? line = reader.ReadLine();
    yield return line!.Split(','); // throws if file empty
}

try
{
    var rows = ReadBadCsv("empty.csv"); // no exception yet
    foreach (var row in rows)          // NullReferenceException here
        Import(row);
}
catch (NullReferenceException) { /* caller's stack, not iterator's */ }
